Member Description Constructor <code>(apiHost, apiPort, responseEventType, source)</code> Initializes the base <code>WorkerBase</code> and creates an <code>ApiClient</code> at <code>apiHost:apiPort</code> <code>ProcessAsync(CloudEvent, ApiClient)</code> Abstract — override to process events with pre-configured API access <code>ApiClient</code> property The configured client for calling backend services <pre><code>using CloudNative.CloudEvents;
using Virtufin.Worker.DevKit;

public class MyApiWorker : ApiWorker
{
    public MyApiWorker()
        : base("localhost", 5002, "my.response", new Uri("urn:my-api-worker")) { }

    protected override async Task&lt;CloudEvent?&gt; ProcessAsync(CloudEvent input, ApiClient api)
    {
        var result = await api.InvokeAsync("target-service", "SomeMethod", new { key = "value" });
        return Response(input, "process", true, message: $"Result: {result}");
    }
}
</code></pre>

Member Description Constructor <code>(apiHost, apiPort, responseEventType, source)</code> Initializes the base <code>CommandWorker</code> and <code>ApiClient</code> <code>HandleCommandAsync(input, command, node)</code> Abstract — same as <code>CommandWorker</code>, with <code>ApiClient</code> available <code>ApiClient</code> property The configured client for calling backend services <pre><code>using System.Text.Json.Nodes;
using CloudNative.CloudEvents;
using Virtufin.Worker.DevKit;

public class MyApiCommandWorker : ApiCommandWorker
{
    public MyApiCommandWorker()
        : base("localhost", 5002, "my.response", new Uri("urn:my-api-command-worker")) { }

    protected override async Task&lt;CloudEvent?&gt; HandleCommandAsync(
        CloudEvent input, string command, JsonNode node)
    {
        var result = await ApiClient.InvokeAsync("target-service", command, node);
        return Response(input, command, true, message: result?.ToString());
    }
}
</code></pre>
